param([Parameter(Mandatory)][string]$OutputPath,[string]$InputPath=(Join-Path $PSScriptRoot '../../../planning/stage-2/repos/dotj-core/evidence/utf8-replacement-contract-v10.0.12.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
$input=Get-Content -LiteralPath $InputPath -Raw -Encoding UTF8|ConvertFrom-Json
$encoding=[Text.UTF8Encoding]::new($false,$true)
function Capture([scriptblock]$Action){try{& $Action}catch{$e=$_.Exception;while(($e -is [Management.Automation.RuntimeException] -or $e -is [Reflection.TargetInvocationException]) -and $null -ne $e.InnerException){$e=$e.InnerException};$record=[ordered]@{ok=$false;exception=$e.GetType().FullName;hResult=$e.HResult;paramName=$e.ParamName;index=$e.Index};if($e -is [Text.EncoderFallbackException]){$record.charUnknown=[int]$e.CharUnknown;$record.charUnknownHigh=[int]$e.CharUnknownHigh;$record.charUnknownLow=[int]$e.CharUnknownLow;$record.isUnknownSurrogate=$e.IsUnknownSurrogate()}else{$record.bytesUnknown=[int[]]$e.BytesUnknown};return $record}}
$texts=@(foreach($row in $input.textRows){$text=[string]::new([char[]][int[]]$row.units);[ordered]@{units=$row.units;result=(Capture {$bytes=$encoding.GetBytes($text);[ordered]@{ok=$true;bytes=[int[]]$bytes;count=$encoding.GetByteCount($text)}});countResult=(Capture {[ordered]@{ok=$true;count=$encoding.GetByteCount($text)}})}})
$bytes=@(foreach($row in $input.byteRows){$buffer=[byte[]]$row.bytes;[ordered]@{bytes=$row.bytes;result=(Capture {$chars=$encoding.GetChars($buffer);[ordered]@{ok=$true;units=[int[]]$chars;count=$encoding.GetCharCount($buffer)}});countResult=(Capture {[ordered]@{ok=$true;count=$encoding.GetCharCount($buffer)}})}})
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();inputSha256=(Get-FileHash -LiteralPath $InputPath -Algorithm SHA256).Hash.ToLowerInvariant();textRows=$texts;byteRows=$bytes;qualification='SELECTED_STATELESS_STRICT_UTF8_ONLY; CUSTOM_FALLBACK_STATEFUL_POINTER_AND_TASK_ACCEPTANCE_OPEN'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 10)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS pinned strict UTF-8: $($texts.Count) text and $($bytes.Count) byte vectors"
